-- 1/15 — WSQ - Technical Drawing with AutoCAD (TGS-2021005538), 2024-01-09
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Learning AutoCAD in Singapore: A Practical Guide to Technical Drawing (WSQ-Funded)', 'autocad-technical-drawing-course-singapore-guide', '2D technical drafting in AutoCAD — the drawing standard almost every engineering and construction firm in Singapore still runs on. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> 2. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>D technical drafting in AutoCAD — the drawing standard almost every engineering and construction firm in Singapore still runs on <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-technical-drawing-with-autocad.html">WSQ - Technical Drawing with AutoCAD</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>AutoCAD is still the baseline literacy of the drawing office. Job ads for draughting and technical roles in Singapore list it more often than any other CAD package, and it is the format most consultants and contractors exchange files in.</p> <h2>Who this course is for</h2> <p>It is aimed at draughtsmen, engineering technicians, renovation and M&amp;E staff, and career switchers moving into design support roles. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>AutoCAD interface, units and drawing setup</strong></li><li><strong>Precision drawing: coordinates, object snaps and constraints</strong></li><li><strong>Layers, blocks, hatching and annotation to drawing standards</strong></li><li><strong>Dimensioning, layouts, plotting and DWG handover</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $680 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-technical-drawing-with-autocad.html">WSQ - Technical Drawing with AutoCAD</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-01-09', 'TGS-2021005538', 'TGS-2021005538', 'Learning AutoCAD in Singapore: A Practical Guide to Technical Drawing (WSQ-Funded)', 'Technical Drawing with AutoCAD in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'autocad course singapore, wsq autocad training, learn autocad singapore, technical drawing course, autocad 2d drafting course, skillsfuture autocad, autocad training funded', '2024-01-09 09:00:00', '2024-01-09 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'autocad-technical-drawing-course-singapore-guide');
SET @pid := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'autocad-technical-drawing-course-singapore-guide');
INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @pid, `tag_id` FROM `tag` WHERE @pid IS NOT NULL AND `name` IN ('AutoCAD', 'Autodesk', 'CAD', 'Technical Drawing');
UPDATE `mmd_blog_post` SET `likes` = 112 WHERE `url_key` = 'autocad-technical-drawing-course-singapore-guide' AND `likes` < 100;

-- 2/15 — WSQ - Architecture Drawing with Revit (TGS-2021004287), 2024-02-02
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Revit for Architectural Drawing: The Singapore BIM Starting Point (WSQ-Funded)', 'revit-architecture-drawing-course-singapore-guide', 'Architectural modelling and documentation in Revit — walls, levels, families and construction drawings produced from a single coordinated model. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> A. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>rchitectural modelling and documentation in Revit — walls, levels, families and construction drawings produced from a single coordinated model <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-architecture-drawing-with-revit.html">WSQ - Architecture Drawing with Revit</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>Singapore''s BCA has driven BIM adoption hard across the built environment, and Revit is the dominant architectural authoring tool. Moving from 2D drafting to model-based documentation is now the main skills gap in most architectural offices here.</p> <h2>Who this course is for</h2> <p>It is aimed at architectural assistants, interior designers, BIM coordinators and draughtsmen moving from 2D CAD into BIM. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>Revit interface, levels, grids and project setup</strong></li><li><strong>Modelling walls, floors, roofs, doors and windows</strong></li><li><strong>Families, components and schedules</strong></li><li><strong>Producing coordinated plans, sections, elevations and sheets</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $720 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-architecture-drawing-with-revit.html">WSQ - Architecture Drawing with Revit</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-02-02', 'TGS-2021004287', 'TGS-2021004287', 'Revit for Architectural Drawing: The Singapore BIM Starting Point (WSQ-Funded)', 'Architecture Drawing with Revit in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'revit course singapore, wsq revit training, learn revit singapore, revit architecture course, bim course singapore, skillsfuture revit, revit training funded', '2024-02-02 09:00:00', '2024-02-02 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'revit-architecture-drawing-course-singapore-guide');
