-- 4/15 — WSQ - Product Design with Fusion 360 (TGS-2021005540), 2024-03-21
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Fusion 360 for Product Design and Manufacturing in Singapore (WSQ-Funded)', 'fusion-360-product-design-course-singapore-guide', 'Parametric product design in Fusion 360 — sketching, solid modelling, assemblies and the CAD-to-CAM path to an actual manufactured part. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> P. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>arametric product design in Fusion 360 — sketching, solid modelling, assemblies and the CAD-to-CAM path to an actual manufactured part <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-product-design-with-fusion-360.html">WSQ - Product Design with Fusion 360</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>Fusion 360 collapses CAD, CAM and simulation into one affordable tool, which is why Singapore''s hardware startups and small manufacturers keep standardising on it. For a designer who needs to get a part actually made, it removes the handoff between design and machining.</p> <h2>Who this course is for</h2> <p>It is aimed at product designers, mechanical engineers, makers, hardware startup founders and manufacturing staff moving into design. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>Sketching, constraints and parametric solid modelling</strong></li><li><strong>Assemblies, joints and motion</strong></li><li><strong>Surfacing, sheet metal and design for manufacture</strong></li><li><strong>Rendering, drawings and CAM toolpaths</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $680 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-product-design-with-fusion-360.html">WSQ - Product Design with Fusion 360</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-03-21', 'TGS-2021005540', 'TGS-2021005540', 'Fusion 360 for Product Design and Manufacturing in Singapore (WSQ-Funded)', 'Product Design with Fusion 360 in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'fusion 360 course singapore, wsq fusion 360 training, product design course singapore, cad cam course, 3d modelling course singapore, skillsfuture fusion 360', '2024-03-21 09:00:00', '2024-03-21 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'fusion-360-product-design-course-singapore-guide');
SET @pid := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'fusion-360-product-design-course-singapore-guide');
INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @pid, `tag_id` FROM `tag` WHERE @pid IS NOT NULL AND `name` IN ('Fusion 360', 'Autodesk', 'Product Design', 'Manufacturing');
UPDATE `mmd_blog_post` SET `likes` = 189 WHERE `url_key` = 'fusion-360-product-design-course-singapore-guide' AND `likes` < 100;

-- 5/15 — WSQ - Product Design with Autodesk Inventor (TGS-2021006715), 2024-04-14
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Autodesk Inventor for Mechanical Product Design in Singapore (WSQ-Funded)', 'autodesk-inventor-product-design-course-singapore-guide', 'Mechanical design in Inventor — parametric parts, large assemblies, sheet metal and production drawings for engineered products. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> M. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>echanical design in Inventor — parametric parts, large assemblies, sheet metal and production drawings for engineered products <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-product-design-with-autodesk-inventor.html">WSQ - Product Design with Autodesk Inventor</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>Inventor remains the workhorse for machine and equipment design in Singapore''s precision-engineering sector, where large assemblies and proper production drawings matter more than photoreal renders. Its assembly and BOM tooling is what keeps it in those shops.</p> <h2>Who this course is for</h2> <p>It is aimed at mechanical engineers, machine designers, precision-engineering staff and technical draughtsmen in manufacturing. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>Parametric part modelling and design intent</strong></li><li><strong>Assembly modelling, constraints and interference checking</strong></li><li><strong>Sheet metal, weldments and frame generator</strong></li><li><strong>Drawing views, GD&amp;T annotation and bills of materials</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $720 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-product-design-with-autodesk-inventor.html">WSQ - Product Design with Autodesk Inventor</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-04-14', 'TGS-2021006715', 'TGS-2021006715', 'Autodesk Inventor for Mechanical Product Design in Singapore (WSQ-Funded)', 'Product Design with Autodesk Inventor in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'autodesk inventor course singapore, wsq inventor training, mechanical design course singapore, inventor 3d modelling, precision engineering course, skillsfuture inventor', '2024-04-14 09:00:00', '2024-04-14 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'autodesk-inventor-product-design-course-singapore-guide');
