-- 8/15 — WSQ - Technical Drawing with AutoCAD Mechanical (TGS-2023037469), 2024-06-25
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'AutoCAD Mechanical for Production Drawings in Singapore (WSQ-Funded)', 'autocad-mechanical-course-singapore-guide', 'Mechanical drafting in AutoCAD Mechanical — standard parts libraries, mechanical dimensioning, GD&amp;T and automatic BOM generation. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> M. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>echanical drafting in AutoCAD Mechanical — standard parts libraries, mechanical dimensioning, GD&amp;T and automatic BOM generation <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-technical-drawing-with-autocad-mechanical.html">WSQ - Technical Drawing with AutoCAD Mechanical</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>AutoCAD Mechanical is plain AutoCAD with the mechanical drudgery removed — a fastener library instead of redrawing bolts, and parts lists that update themselves. For a drawing office producing production sets weekly, that is hours back per drawing.</p> <h2>Who this course is for</h2> <p>It is aimed at mechanical draughtsmen, design engineers and manufacturing staff producing production drawings. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>AutoCAD Mechanical environment and drawing standards (ISO/ANSI/JIS)</strong></li><li><strong>Standard parts, fasteners and shaft generator</strong></li><li><strong>Mechanical dimensioning, tolerancing and GD&amp;T</strong></li><li><strong>Balloons, parts lists and automatic BOM</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $900 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-technical-drawing-with-autocad-mechanical.html">WSQ - Technical Drawing with AutoCAD Mechanical</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-06-25', 'TGS-2023037469', 'TGS-2023037469', 'AutoCAD Mechanical for Production Drawings in Singapore (WSQ-Funded)', 'Technical Drawing with AutoCAD Mechanical in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'autocad mechanical course singapore, wsq autocad mechanical, mechanical drafting course, production drawing course, gd&t course singapore, skillsfuture autocad mechanical', '2024-06-25 09:00:00', '2024-06-25 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'autocad-mechanical-course-singapore-guide');
SET @pid := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'autocad-mechanical-course-singapore-guide');
INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @pid, `tag_id` FROM `tag` WHERE @pid IS NOT NULL AND `name` IN ('AutoCAD', 'Autodesk', 'Mechanical Design', 'Technical Drawing');
UPDATE `mmd_blog_post` SET `likes` = 143 WHERE `url_key` = 'autocad-mechanical-course-singapore-guide' AND `likes` < 100;

-- 9/15 — Application of BIM using Revit (TGS-2026064717), 2024-07-19
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Applying BIM with Revit: From Model to Coordinated Delivery (WSQ-Funded)', 'application-of-bim-using-revit-course-singapore-guide', 'BIM as a delivery process rather than a modelling exercise — model coordination, information management and how a BIM deliverable is actually structured. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> B. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>IM as a delivery process rather than a modelling exercise — model coordination, information management and how a BIM deliverable is actually structured <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-application-of-bim-using-revit.html">Application of BIM using Revit</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>BCA''s BIM submission requirements mean a model is a contractual deliverable, not an internal drawing aid. Teams that treat BIM as ''Revit with extra steps'' produce models that fail coordination; the process knowledge is what actually gets a submission through.</p> <h2>Who this course is for</h2> <p>It is aimed at BIM coordinators, project engineers, architects and consultants delivering BIM-mandated projects in Singapore. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>BIM concepts, standards and the Singapore delivery context</strong></li><li><strong>Model setup, worksharing and collaboration</strong></li><li><strong>Coordination, clash awareness and model checking</strong></li><li><strong>Information management, schedules and BIM deliverables</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $720 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-application-of-bim-using-revit.html">Application of BIM using Revit</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-07-19', 'TGS-2026064717', 'TGS-2026064717', 'Applying BIM with Revit: From Model to Coordinated Delivery (WSQ-Funded)', 'Application of BIM using Revit in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'bim course singapore, wsq bim revit, application of bim using revit, bca bim course, bim coordinator training, skillsfuture bim course', '2024-07-19 09:00:00', '2024-07-19 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'application-of-bim-using-revit-course-singapore-guide');
