-- 10/15 — WSQ - Generative AI for 3D Modeling (TGS-2023037544), 2024-08-12
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Generative AI for 3D Modeling: What It Actually Changes for Designers (WSQ-Funded)', 'generative-ai-for-3d-modeling-course-singapore-guide', 'Applying generative AI to 3D modelling workflows — AI-assisted concept generation, generative design studies and how they feed back into a production CAD model. Who it suits, what you will learn, what it costs after WSQ funding (50% for SG/PR 21+, 70% at 40+), and how to decide if it is your right next step.', '<p><strong>Short version:</strong> A. This guide covers what the course teaches, who it suits, what it costs after WSQ funding, and how to decide whether it is the right next step for you.</p>pplying generative AI to 3D modelling workflows — AI-assisted concept generation, generative design studies and how they feed back into a production CAD model <p>Our <a href="https://www.tertiarycourses.com.sg/wsq-generative-ai-for-3d-modeling.html">WSQ - Generative AI for 3D Modeling</a> course runs hands-on in Singapore and is WSQ-funded, so most Singaporeans and PRs pay a fraction of the listed fee. Here is the honest picture.</p> <h2>Why this software, and why here</h2> <p>Generative tools are good at producing many candidate forms fast and bad at knowing which one is manufacturable. The skill worth having is directing the exploration and then judging the output — which is exactly the part that does not get automated.</p> <h2>Who this course is for</h2> <p>It is aimed at product designers, architects, visualisers and engineers who already model in 3D and want the AI-assisted workflow. You do not need a design degree — you need to be comfortable with a computer and willing to work through hands-on exercises.</p> <h2>What you will actually learn</h2> <ol><li><strong>Generative AI concepts for 3D and design workflows</strong></li><li><strong>AI-assisted concept generation and iteration</strong></li><li><strong>Generative design studies: goals, constraints and outcomes</strong></li><li><strong>Taking AI output into a production CAD model</strong></li></ol> <h2>What it costs after funding</h2> <table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody><tr><td>Course fee (before GST)</td><td>$%d</td></tr><tr><td>Course fee (incl. 9%% GST)</td><td>$%d</td></tr><tr><td>WSQ funding, SG/PR aged 21+</td><td>50%% of course fee</td></tr><tr><td>WSQ funding, SG aged 40+ (MCES)</td><td>70%% of course fee</td></tr><tr><td>SkillsFuture Credit</td><td>Claimable on the balance</td></tr></tbody></table> <p>PSEA, UTAP (NTUC members) and SFEC (for company-sponsored staff) may also apply. Final eligibility is subject to verification — ask us before enrolling and we will walk you through what you qualify for.</p> <h2>Frequently asked questions</h2> <h3>Do I need prior experience to join?</h3><p>No formal prerequisite beyond basic computer literacy. If you have never drawn or modelled before, expect to work harder in the first half-day — but people do start from zero. The class is taught hands-on, so you build as you learn rather than watching slides.</p> <h3>How much will I actually pay?</h3><p>The listed fee is $1600 before GST. At 50% WSQ funding you pay roughly half; at 70% (Singaporeans aged 40 and above) noticeably less again. SkillsFuture Credit can then offset the balance, which for many learners brings the cash outlay close to zero.</p> <h3>Is this course WSQ-certified?</h3><p>Yes. It is a WSQ course under the SkillsFuture Singapore framework, which is what makes the funding and SkillsFuture Credit available. You will need to meet the attendance and assessment requirements to be certified and for funding to be disbursed.</p> <h3>What software version do you teach on?</h3><p>We teach on a current Autodesk release, and the skills carry across versions — the interface shifts a little between releases but the underlying workflow does not. If your office runs an older version, tell your trainer and they will point out the differences.</p> <h3>Will I be able to use this at work straight away?</h3><p>That is the intent. The exercises are built around realistic tasks rather than toy examples, so the workflow you practise is the one you will repeat on the job.</p> <h2>Next step</h2> <p>If this matches the work you do — or the work you want to move into — <a href="https://www.tertiarycourses.com.sg/wsq-generative-ai-for-3d-modeling.html">WSQ - Generative AI for 3D Modeling</a> is the course page, with the current schedule and the funding breakdown. Claim up to 70% WSQ funding or use your SkillsFuture Credit.</p> <p><em>Course fees, funding tiers and software versions change. Figures here were correct at the time of writing — confirm the current position on the course page before enrolling.</em></p>', 'Tertiary Infotech Academy', 1, '2024-08-12', 'TGS-2023037544', 'TGS-2023037544', 'Generative AI for 3D Modeling: What It Actually Changes for Designers (WSQ-Funded)', 'Generative AI for 3D Modeling in Singapore — WSQ-funded, hands-on. What you learn, who it is for, and the real cost after 50-70% WSQ funding and SkillsFuture Credit.', 'generative ai 3d modeling course, wsq generative ai design, ai 3d modelling singapore, generative design course, ai for designers singapore, skillsfuture generative ai', '2024-08-12 09:00:00', '2024-08-12 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'generative-ai-for-3d-modeling-course-singapore-guide');
